SELECT UTC_TIMESTAMP(3) observed_utc;
SELECT r.account_id,r.task_id,r.group_execution_id,r.role_type,r.released_at IS NOT NULL released,t.status task_status,e.execution_status FROM pull_task_group_account r JOIN pull_task t ON t.id=r.task_id AND t.tenant_id=r.tenant_id JOIN pull_task_group_execution e ON e.id=r.group_execution_id AND e.tenant_id=r.tenant_id WHERE r.account_id IN(1038,1736,2755,2757) AND r.released_at IS NULL;
SELECT 'active_pull_roles' metric,COUNT(*) rows_count,COUNT(DISTINCT r.task_id) task_count FROM pull_task_group_account r JOIN pull_task_group_execution e ON e.id=r.group_execution_id AND e.tenant_id=r.tenant_id WHERE r.account_id IN(1038,1736,2755,2757) AND e.execution_status IN(0,1,2,3) AND r.released_at IS NULL
UNION ALL SELECT 'marketing_occupancy',COUNT(*),COUNT(DISTINCT marketing_task_id) FROM marketing_account_occupancy WHERE account_id IN(1038,1736,2755,2757)
UNION ALL SELECT 'active_join_results',COUNT(*),COUNT(DISTINCT t.id) FROM join_task_result r JOIN join_task t ON t.id=r.join_task_id AND t.tenant_id=r.tenant_id WHERE r.account_id IN(1038,1736,2755,2757) AND t.deleted_at IS NULL AND t.status NOT IN('STOPPED','DONE','FAILED')
UNION ALL SELECT 'active_hyperlink_usage',COUNT(*),COUNT(DISTINCT u.hyperlink_task_id) FROM hyperlink_task_account_usage u JOIN hyperlink_task_runtime t ON t.hyperlink_task_id=u.hyperlink_task_id AND t.tenant_id=u.tenant_id WHERE u.account_id IN(1038,1736,2755,2757) AND (t.run_status IN(0,1,3) OR u.in_flight_count>0)
UNION ALL SELECT 'active_feed',COUNT(*),COUNT(DISTINCT t.id) FROM feed_task_account a JOIN feed_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(1038,1736,2755,2757) AND t.deleted_at IS NULL AND t.task_status IN(0,1,3)
UNION ALL SELECT 'active_contact',COUNT(*),COUNT(DISTINCT t.id) FROM contact_friend_task_account a JOIN contact_friend_task t ON t.id=a.task_id AND t.tenant_id=a.tenant_id WHERE a.account_id IN(1038,1736,2755,2757) AND t.deleted_at IS NULL AND t.run_status IN(0,1,3)
UNION ALL SELECT 'active_group_pull_marketing',COUNT(*),COUNT(DISTINCT task_id) FROM group_pull_marketing_execution WHERE (builder_account_id IN(1038,1736,2755,2757) OR marketing_account_id IN(1038,1736,2755,2757)) AND execution_status IN(1,2,7)
UNION ALL SELECT 'active_historical_pull',COUNT(*),NULL FROM historical_group_pull_execution WHERE (operation_account_id IN(1038,1736,2755,2757) OR puller_account_id IN(1038,1736,2755,2757)) AND (pull_status IN(0,1) OR marketing_status IN(1,2))
UNION ALL SELECT 'active_script_sends',COUNT(*),NULL FROM script_marketing_send_record WHERE account_id IN(1038,1736,2755,2757) AND status IN(1,4,5)
UNION ALL SELECT 'active_mutual_contacts',COUNT(*),NULL FROM account_mutual_contact_item WHERE (actor_id IN(1038,1736,2755,2757) OR target_id IN(1038,1736,2755,2757)) AND status IN(1,2,5)
UNION ALL SELECT 'active_normal_creator',COUNT(*),NULL FROM normal_group_creation_item WHERE creator_account_id IN(1038,1736,2755,2757) AND deleted_at IS NULL AND status IN('PENDING','RUNNING','RESULT_UNKNOWN') AND current_step<>'DONE'
UNION ALL SELECT 'active_normal_member',COUNT(*),NULL FROM normal_group_creation_item_member m JOIN normal_group_creation_item i ON i.id=m.item_id AND i.tenant_id=m.tenant_id WHERE m.member_account_id IN(1038,1736,2755,2757) AND i.deleted_at IS NULL AND i.status IN('PENDING','RUNNING','RESULT_UNKNOWN') AND i.current_step<>'DONE';
SELECT aggregate_type,command_type,status,COUNT(*) n,MIN(FROM_UNIXTIME(created_at/1000)) first_utc,MAX(FROM_UNIXTIME(created_at/1000)) last_utc FROM protocol_command_outbox WHERE deleted_at IS NULL AND (last_error LIKE '%注销%' OR last_error LIKE '%deletion%') GROUP BY aggregate_type,command_type,status;
SELECT a.id,o.aggregate_type,o.command_type,o.status,COUNT(*) n,MAX(FROM_UNIXTIME(o.created_at/1000)) latest_utc FROM account a JOIN protocol_command_outbox o ON o.protocol_account_id=a.protocol_account_id AND o.tenant_id=a.tenant_id WHERE a.id IN(1038,1736,2755,2757) AND o.created_at>=1791302515000 GROUP BY a.id,o.aggregate_type,o.command_type,o.status;
